<script setup lang="ts">
import { computed, onBeforeUnmount, ref, watch } from 'vue';
import { onBeforeRouteLeave } from 'vue-router';
import { Archive, ArrowDown, ArrowUp, BookOpen, Check, ChevronRight, Copy, FileCheck2, Layers3, LoaderCircle, MessageSquareText, Plus, RefreshCw, Save, Search, ShieldCheck, Tags, Trash2, Users, X } from 'lucide-vue-next';
import type { DimensionDraft, GovernanceAccess, GovernanceDimension, GovernanceDirectory, GovernanceTemplate, GovernancePreset, PublishedDimension, PublishedTemplateSnapshot, TemplateDraft,TemplateTargetKind,LabelScope } from '@oxen/shared';
import { post, request } from '../api';
import { useAppStore } from '../stores/app';
import '../styles/label-governance.css';
import {dimensionBindingState,latestPublishedDimension} from '../dimension-binding';

const app=useAppStore(),access=ref<GovernanceAccess>(),directory=ref<GovernanceDirectory>(),presets=ref<GovernancePreset[]>([]),identities=ref<Array<{id:string;name:string}>>([]);
const organizationId=ref(''),tab=ref<'templates'|'dimensions'|'feedback'|'maintainers'>('templates'),domain=ref(''),search=ref(''),selectedId=ref('');
const templateKind=ref<TemplateTargetKind>('dataset'),sort=ref<'updated'|'name'>('updated'),newDomainId=ref(''),newDomainName=ref(''),newDomainDescription=ref(''),domainOpen=ref(false),copySource=ref<{id:string;version:number}>();
const loading=ref(true),busy=ref(false),error=ref(''),notice=ref(''),baseline=ref(''),dimension=ref<DimensionDraft>(),template=ref<TemplateDraft>();
const copyOpen=ref(false),copyPreset=ref('dataset-general'),copyId=ref(''),copyName=ref(''),preview=ref<PublishedDimension|PublishedTemplateSnapshot>();
const organizationName=ref(''),newOrganizationId=ref(''),newOrganizationName=ref(''),maintainerId=ref('');
const feedbackResponse=ref<Record<string,string>>({});let generation=0;
const org=computed(()=>directory.value?.organization),base=computed(()=>'/governance/organizations/'+encodeURIComponent(organizationId.value));
const selectedDimension=computed(()=>org.value?.dimensions.find(item=>item.id===selectedId.value)),selectedTemplate=computed(()=>org.value?.templates.find(item=>item.id===selectedId.value));
const draftState=()=>JSON.stringify(tab.value==='dimensions'?dimension.value:template.value);
const dirty=computed(()=>(!!baseline.value&&draftState()!==baseline.value)||(copyOpen.value&&!!(copyId.value.trim()||copyName.value.trim()))||!!newDomainId.value||!!newDomainName.value||!!newDomainDescription.value);
const domains=computed(()=>[...new Set(['general','ai-safety',...(org.value?.domains?.map(item=>item.id)??[]),...(org.value?.templates.map(item=>item.draft.domain)??[])])]);
const domainName=(value:string)=>org.value?.domains?.find(item=>item.id===value)?.name??({general:'通用','ai-safety':'AI 安全','ai-safety-core':'AI 安全基础','sensitive-data':'敏感数据','prompt-injection':'提示词注入','skill-supply-chain':'Skill 供应链','behavior-drift':'行为偏离'}[value]??value);
const kindName=(kind:TemplateTargetKind)=>({dataset:'数据集标签模板',sample:'样本标签模板',legacy:'旧混合规范（兼容）'}[kind]);
const order=(a:{updatedAt:string;draft:{name?:string;displayName?:string}},b:{updatedAt:string;draft:{name?:string;displayName?:string}})=>sort.value==='name'?(a.draft.name??a.draft.displayName??'').localeCompare(b.draft.name??b.draft.displayName??''):(Date.parse(b.updatedAt)||0)-(Date.parse(a.updatedAt)||0);
const dimensions=computed(()=>org.value?.dimensions.filter(item=>(item.id+' '+item.draft.displayName+' '+item.draft.description).toLowerCase().includes(search.value.toLowerCase())).sort(order)??[]);
const templates=computed(()=>org.value?.templates.filter(item=>(item.draft.targetKind??'legacy')===templateKind.value&&(!domain.value||item.draft.domain===domain.value)&&(item.id+' '+item.draft.name+' '+item.draft.description).toLowerCase().includes(search.value.toLowerCase())).sort(order)??[]);
const filteredPresets=computed(()=>presets.value.filter(item=>item.targetKind===templateKind.value));
const availableScopes=computed<LabelScope[]>(()=>template.value?.targetKind==='dataset'?['dataset']:template.value?.targetKind==='sample'?['row','file']:['dataset','file','row']);
const scopeName=(scope:string)=>({dataset:'数据集',row:'样本',file:'文件附件'}[scope]??scope);
const publishedDimensions=computed(()=>org.value?.dimensions.filter(item=>item.versions.length&&!item.deprecated)??[]);
const existingOptionIds=computed(()=>new Set(selectedDimension.value?.versions.at(-1)?.options.map(option=>option.id)??[]));
function cloneDraft<T>(value:T):T{return JSON.parse(JSON.stringify(value)) as T;}
const typeName=(value:string)=>({single:'单选',multi:'多选',text:'文本'}[value]??value);
const date=(value:string)=>new Date(value).toLocaleString('zh-CN');
async function mayLeave(){if(busy.value)return false;if(!dirty.value)return true;const ok=await app.confirmAction('规范草稿尚未保存，确认放弃并切换吗？',{title:'未保存的规范草稿',confirmLabel:'放弃并切换'});if(ok){newDomainId.value='';newDomainName.value='';newDomainDescription.value='';copyOpen.value=false;}return ok;}
onBeforeRouteLeave(mayLeave);
const unregisterDraftGuard=app.registerDraftGuard(mayLeave);onBeforeUnmount(unregisterDraftGuard);
function beforeUnload(event:BeforeUnloadEvent){if(dirty.value||busy.value){event.preventDefault();event.returnValue='';}}
window.addEventListener('beforeunload',beforeUnload);onBeforeUnmount(()=>{++generation;window.removeEventListener('beforeunload',beforeUnload);});
function fill(){dimension.value=undefined;template.value=undefined;if(tab.value==='dimensions'&&selectedDimension.value)dimension.value=cloneDraft(selectedDimension.value.draft);if(tab.value==='templates'&&selectedTemplate.value)template.value={...cloneDraft(selectedTemplate.value.draft),targetKind:selectedTemplate.value.draft.targetKind??'legacy'};baseline.value=draftState();}
async function loadDirectory(keep=true){const current=++generation;loading.value=true;error.value='';try{const value=await request<GovernanceDirectory>(base.value);if(current!==generation)return;directory.value=value;if(!keep)selectedId.value='';fill();}catch(cause){if(current===generation)error.value=(cause as Error).message;}finally{if(current===generation)loading.value=false;}}
async function initialize(){const current=++generation;loading.value=true;try{const result=await request<GovernanceAccess>('/governance/access');if(current!==generation)return;access.value=result;if(!result.canManage)return;const values=await Promise.all([request<GovernancePreset[]>('/governance/presets'),result.owner?request<Array<{id:string;name:string}>>('/governance/identities'):Promise.resolve([])]);if(current!==generation)return;presets.value=values[0];identities.value=values[1];organizationId.value=result.organizations[0]?.id??'';if(organizationId.value)await loadDirectory(false);}catch(cause){if(current===generation)error.value=(cause as Error).message;}finally{if(current===generation)loading.value=false;}}
void initialize();
watch(()=>app.status?.identity?.id,(identity,previous)=>{if(identity===previous)return;++generation;directory.value=undefined;access.value=undefined;dimension.value=undefined;template.value=undefined;baseline.value='';selectedId.value='';copyOpen.value=false;preview.value=undefined;void initialize();});
async function chooseOrganization(id:string,element?:HTMLSelectElement){if(id===organizationId.value)return;if(!await mayLeave()){if(element)element.value=organizationId.value;return;}organizationId.value=id;selectedId.value='';domain.value='';await loadDirectory(false);}
async function chooseDomain(id:string,element?:HTMLSelectElement){if(id===domain.value)return;if(!await mayLeave()){if(element)element.value=domain.value;return;}domain.value=id;selectedId.value='';fill();}
async function refreshDirectory(){if(await mayLeave())await loadDirectory();}
async function chooseTab(value:typeof tab.value){if(value===tab.value||!await mayLeave())return;tab.value=value;selectedId.value='';search.value='';fill();}
async function select(id:string){if(id===selectedId.value||!await mayLeave())return;selectedId.value=id;error.value='';fill();}
async function createDimension(){if(!await mayLeave())return;selectedId.value='';dimension.value={id:'',displayName:'',description:'',type:'single',options:[]};baseline.value=draftState();}
async function chooseTemplates(kind:TemplateTargetKind){if(tab.value==='templates'&&templateKind.value===kind)return true;if(!await mayLeave())return false;tab.value='templates';templateKind.value=kind;selectedId.value='';fill();return true;}
const sidebarTemplates=(kind:TemplateTargetKind)=>(org.value?.templates??[]).filter(item=>(item.draft.targetKind??'legacy')===kind&&(!domain.value||item.draft.domain===domain.value)).sort(order);
async function selectFromSidebar(kind:TemplateTargetKind,id:string){if(await chooseTemplates(kind))await select(id);}
async function createTemplate(){if(!await mayLeave())return;selectedId.value='';template.value={id:'',name:'',domain:domain.value||'general',targetKind:templateKind.value,description:'',bindings:[]};baseline.value=draftState();}
async function run(action:()=>Promise<unknown>,message:string){if(busy.value)return false;busy.value=true;error.value='';notice.value='';const current=generation;try{await action();if(current!==generation)return false;notice.value=message;await loadDirectory();return true;}catch(cause){if(current===generation)error.value=(cause as Error).message;return false;}finally{busy.value=false;}}
async function saveDimension(){if(!dimension.value)return;const value=cloneDraft(dimension.value);if(!value.semanticKey?.trim())delete value.semanticKey;if(value.type==='text')value.options=[];for(const option of value.options)if(!option.legacyValue?.trim())delete option.legacyValue;if(await run(()=>post(base.value+'/dimensions',{draft:value,expectedRevision:selectedDimension.value?.revision??0}),'维度草稿已保存；发布后才能用于模板')){selectedId.value=value.id;fill();}}
async function saveTemplate(){if(!template.value)return;template.value.bindings.forEach((binding,index)=>{binding.order=index;});const value=cloneDraft(template.value);if(await run(()=>post(base.value+'/templates',{draft:value,expectedRevision:selectedTemplate.value?.revision??0}),'模板草稿已保存')){selectedId.value=value.id;fill();}}
async function publish(kind:'dimensions'|'templates'){const item=kind==='dimensions'?selectedDimension.value:selectedTemplate.value;if(!item||dirty.value)return;if(!await app.confirmAction('发布后该版本不可改写；后续调整需发布新版本。确认发布当前草稿？',{title:'发布规范版本',confirmLabel:'发布版本'}))return;await run(()=>post(base.value+'/'+kind+'/'+encodeURIComponent(item.id)+'/publish',{expectedRevision:item.revision}),'已发布不可变版本');}
async function deprecate(kind:'dimensions'|'templates'){const item=kind==='dimensions'?selectedDimension.value:selectedTemplate.value;if(!item||!await mayLeave()||!await app.confirmAction('弃用后不能用于新绑定；历史版本与已采用的数据保持可读。',{title:'弃用规范定义',confirmLabel:'确认弃用'}))return;await run(()=>post(base.value+'/'+kind+'/'+encodeURIComponent(item.id)+'/deprecate',{expectedRevision:item.revision}),'定义已弃用，历史版本保留');}
function addOption(){dimension.value?.options.push({id:'',displayName:'',description:''});}
function addBinding(){const value=publishedDimensions.value[0],latest=latestPublishedDimension(value);if(!template.value||!value||!latest)return;template.value.bindings.push({dimensionId:value.id,dimensionVersion:latest.version,scopes:template.value.targetKind==='dataset'?['dataset']:['row'],required:false,order:template.value.bindings.length,defaultVisible:true});}
function changeTemplateKind(){if(!template.value)return;for(const binding of template.value.bindings){binding.scopes=binding.scopes.filter(scope=>availableScopes.value.includes(scope));if(!binding.scopes.length)binding.scopes=template.value.targetKind==='dataset'?['dataset']:['row'];}}
function bindingDimension(id:string){return org.value?.dimensions.find(item=>item.id===id);}
function bindingStatus(id:string,version:number){return dimensionBindingState(bindingDimension(id),version);}
function updateBinding(index:number){const binding=template.value?.bindings[index],latest=latestPublishedDimension(binding?bindingDimension(binding.dimensionId):undefined);if(binding&&latest)binding.dimensionVersion=latest.version;}
function moveBinding(index:number,direction:number){const items=template.value?.bindings;if(!items||!items[index+direction])return;[items[index],items[index+direction]]=[items[index+direction]!,items[index]!];}
async function copy(){if(!copyId.value.trim()||!copyName.value.trim())return;const source=copySource.value;if(await run(()=>source?post(base.value+'/templates/'+source.id+'/copy',{id:copyId.value.trim(),name:copyName.value.trim(),sourceVersion:source.version}):post(base.value+'/templates/from-preset',{presetId:copyPreset.value,id:copyId.value.trim(),name:copyName.value.trim()}),'已另存组织模板草稿，需审核并发布')){copyOpen.value=false;tab.value='templates';selectedId.value=copyId.value.trim();fill();}}
async function openCopy(){if(!await mayLeave())return;copySource.value=undefined;copyPreset.value=filteredPresets.value[0]?.id??'';copyId.value='';copyName.value='';copyOpen.value=true;}
async function copyPublished(){if(!selectedTemplate.value?.versions.length||!await mayLeave())return;copySource.value={id:selectedTemplate.value.id,version:selectedTemplate.value.versions.at(-1)!.version};copyId.value='';copyName.value=selectedTemplate.value.draft.name+' 副本';copyOpen.value=true;}
async function saveDomain(){if(busy.value||!org.value||!newDomainId.value||!newDomainName.value)return;busy.value=true;error.value='';const held={dimension:dimension.value,template:template.value,baseline:baseline.value};try{await post(base.value+'/domains',{domain:{id:newDomainId.value,name:newDomainName.value,description:newDomainDescription.value},expectedRevision:org.value.revision});newDomainId.value='';newDomainName.value='';newDomainDescription.value='';domainOpen.value=false;await loadDirectory();dimension.value=held.dimension;template.value=held.template;baseline.value=held.baseline;notice.value='组织领域已新增，现有模板草稿保持。';}catch(cause){error.value=(cause as Error).message;}finally{busy.value=false;}}
async function grantMaintainer(id:string,enabled:boolean){if(!org.value)return;await run(()=>post(base.value+'/maintainers',{identityId:id,enabled,expectedRevision:org.value!.revision}),enabled?'已指定组织维护者':'已撤销组织维护者');}
async function createOrganization(){if(busy.value)return;busy.value=true;error.value='';try{await post('/governance/organizations',{id:newOrganizationId.value.trim(),name:newOrganizationName.value.trim()});newOrganizationId.value='';newOrganizationName.value='';await initialize();}catch(cause){error.value=(cause as Error).message;}finally{busy.value=false;}}
async function respond(id:string,status:'resolved'|'declined'){const response=feedbackResponse.value[id]?.trim();if(!response)return;await run(()=>post(base.value+'/feedback/'+id+'/respond',{status,response}),'反馈处理结果已记录');}
</script>

<template>
  <main class="page governance-page">
    <header class="governance-heading"><div><p class="eyebrow">LABEL GOVERNANCE</p><h1>标签管理</h1><p>集中维护规范，发布稳定版本；样本标注在项目的数据编辑中完成。</p></div><span class="governance-role"><ShieldCheck :size="16"/>{{access?.owner?'实例管理员':'组织规范维护者'}}</span></header>
    <p v-if="error" class="error-state" role="alert">{{error}}</p><p v-if="notice" class="governance-notice" role="status"><Check :size="16"/>{{notice}}</p>
    <div v-if="loading&&!directory" class="empty"><LoaderCircle :size="26" class="spin"/>正在核对规范管理权限…</div>
    <section v-else-if="!access?.canManage" class="panel empty"><ShieldCheck :size="32"/><h2>当前身份没有规范管理权限</h2><p>标注与复核人员可在已授权项目中使用已发布规范；管理入口仅向实例管理员及指定组织维护者开放。</p></section>
    <div v-else class="governance-shell">
      <div class="governance-filters"><label>组织<select :value="organizationId" :disabled="busy" @change="chooseOrganization(($event.target as HTMLSelectElement).value,$event.target as HTMLSelectElement)"><option v-for="item in access.organizations" :key="item.id" :value="item.id">{{item.name}}</option></select></label><label>领域<select :value="domain" :disabled="busy" @change="chooseDomain(($event.target as HTMLSelectElement).value,$event.target as HTMLSelectElement)"><option value="">全部领域</option><option v-for="item in domains" :key="item" :value="item">{{domainName(item)}}</option></select></label><label>目录排序<select v-model="sort"><option value="updated">最近更新</option><option value="name">名称</option></select></label><button class="btn btn-ghost" :disabled="busy" @click="domainOpen=!domainOpen"><Plus :size="14"/>新增组织领域</button><span v-if="tab==='dimensions'" class="muted">维度字典跨领域共享；领域筛选用于模板目录。</span></div>
      <form v-if="domainOpen" class="governance-domain-form panel" @submit.prevent="saveDomain"><h3>新增领域</h3><label>稳定 ID<input v-model="newDomainId" required pattern="[a-z][a-z0-9_-]*" maxlength="64" placeholder="例如 agent-security"/></label><label>名称<input v-model="newDomainName" required maxlength="80"/></label><label>说明<input v-model="newDomainDescription" maxlength="2000"/></label><button class="btn" :disabled="busy">保存领域</button></form>
      <aside class="governance-sidebar"><div class="governance-nav-caption">规范目录</div><template v-for="kind in (['dataset','sample'] as const)" :key="kind"><button :class="{active:tab==='templates'&&templateKind===kind}" @click="chooseTemplates(kind)"><Layers3 :size="17"/>{{kindName(kind)}}<span>{{sidebarTemplates(kind).length}}</span></button><button v-for="item in sidebarTemplates(kind)" :key="item.id" class="governance-template-link" :class="{selected:tab==='templates'&&selectedId===item.id}" @click="selectFromSidebar(kind,item.id)">{{item.draft.name}}</button></template><button :class="{active:tab==='dimensions'}" @click="chooseTab('dimensions')"><Tags :size="17"/>维度字典<span>{{org?.dimensions.length??0}}</span></button><button v-if="sidebarTemplates('legacy').length" :class="{active:tab==='templates'&&templateKind==='legacy'}" @click="chooseTemplates('legacy')"><Archive :size="16"/>旧混合规范<span>{{sidebarTemplates('legacy').length}}</span></button><button :class="{active:tab==='feedback'}" @click="chooseTab('feedback')"><MessageSquareText :size="17"/>缺项反馈<span>{{directory?.feedback.filter(item=>item.status==='open').length??0}}</span></button><button v-if="access.owner" :class="{active:tab==='maintainers'}" @click="chooseTab('maintainers')"><Users :size="17"/>指定维护者</button><p class="governance-sidebar-note">规范管理权不包含私有样本读取权。保存草稿不会提交项目；发布与项目采用分别执行。</p></aside>
      <section class="governance-content">
        <div v-if="!org" class="panel empty"><Layers3 :size="28"/><h2>还没有可管理的组织</h2><p>由实例管理员创建组织并指定维护者。</p></div>
        <template v-else-if="tab==='templates'||tab==='dimensions'">
          <header class="governance-toolbar"><div><h2>{{tab==='templates'?kindName(templateKind):'维度字典'}}</h2><p>{{tab==='templates'?'模板绑定已发布维度，定义适用层级、顺序与必填约束。':'稳定 ID 与显示名称分离，已用选项弃用后仍可追溯。'}}</p></div><div><button class="btn btn-ghost" :disabled="busy" @click="refreshDirectory"><RefreshCw :size="15"/>刷新</button><button v-if="tab==='templates'" class="btn" :disabled="busy" @click="openCopy"><Copy :size="15"/>从预设另存</button><button class="btn btn-primary" :disabled="busy" @click="tab==='templates'?createTemplate():createDimension()"><Plus :size="16"/>{{tab==='templates'?'新建模板':'新建维度'}}</button></div></header>
          <div class="governance-workspace"><div class="governance-list"><label class="search-field"><Search :size="15"/><input v-model="search" aria-label="搜索规范" placeholder="搜索 ID、名称或说明…"/></label><template v-if="tab==='templates'"><button v-for="item in templates" :key="item.id" :class="{selected:selectedId===item.id}" @click="select(item.id)"><span><strong>{{item.draft.name}}</strong><i :class="{deprecated:item.deprecated}">{{item.deprecated?'已弃用':item.versions.length?'已发布 v'+item.versions.at(-1)!.version:'草稿'}}</i></span><code>{{item.id}}</code><small>{{domainName(item.draft.domain)}} · {{item.draft.bindings.length}} 个维度</small></button><p v-if="!templates.length" class="governance-list-empty">暂无匹配的模板，从预设另存或创建组织规范。</p></template><template v-else><button v-for="item in dimensions" :key="item.id" :class="{selected:selectedId===item.id}" @click="select(item.id)"><span><strong>{{item.draft.displayName}}</strong><i>{{item.deprecated?'已弃用':item.versions.length?'v'+item.versions.at(-1)!.version:'草稿'}}</i></span><code>{{item.id}}</code><small>{{typeName(item.draft.type)}} · {{item.draft.options.length}} 个选项</small></button><p v-if="!dimensions.length" class="governance-list-empty">暂无匹配的维度。</p></template></div>
            <section class="governance-editor">
              <div v-if="!dimension&&!template" class="empty"><BookOpen :size="32"/><h3>选择规范查看详情</h3><p>草稿可编辑，已发布版本保留原样。</p></div>
              <form v-else-if="dimension" @submit.prevent="saveDimension"><div class="governance-editor-title"><div><h3>{{selectedDimension?'编辑维度草稿':'新建标签维度'}}</h3><p>发布后 ID、类型和选项标识稳定；显示名称与释义可发布新版。</p></div><span v-if="dirty" class="badge">未保存</span></div><fieldset :disabled="busy||selectedDimension?.deprecated"><div class="governance-form-grid"><label>ID<input v-model="dimension.id" required pattern="[a-z][a-z0-9_-]*" maxlength="64" :readonly="!!selectedDimension" placeholder="例如 source"/></label><label>显示名称<input v-model="dimension.displayName" required maxlength="80" placeholder="例如 数据来源"/></label><label>类型<select v-model="dimension.type" :disabled="!!selectedDimension?.versions.length"><option value="single">单选</option><option value="multi">多选</option><option value="text">文本</option></select></label><label>语义键<input v-model="dimension.semanticKey" :readonly="!!selectedDimension?.versions.length" placeholder="可选，例如 general.data_source"/></label></div><label>判定说明<textarea v-model="dimension.description" rows="3" maxlength="2000" placeholder="说明含义、边界与选项使用方法…"/></label><section v-if="dimension.type!=='text'" class="governance-options"><header><strong>选项</strong><button type="button" class="btn btn-ghost" @click="addOption"><Plus :size="14"/>增加选项</button></header><div v-for="(option,index) in dimension.options" :key="index" class="governance-option"><div class="governance-form-grid"><label>稳定 ID<input v-model="option.id" required pattern="[a-z][a-z0-9_-]*" :readonly="existingOptionIds.has(option.id)" maxlength="64"/></label><label>显示名<input v-model="option.displayName" required maxlength="120"/></label></div><label>说明<input v-model="option.description" maxlength="1000"/></label><details class="governance-option-compat"><summary>旧标签兼容值（可选）</summary><label>原有值<input v-model="option.legacyValue" :readonly="existingOptionIds.has(option.id)" maxlength="120" placeholder="仅迁移旧标签时填写，发布后不可更改"/></label></details><div><label class="governance-check"><input v-model="option.deprecated" type="checkbox"/>弃用（历史仍可读）</label><button v-if="!existingOptionIds.has(option.id)" type="button" class="icon-button" aria-label="移除未发布选项" @click="dimension.options.splice(index,1)"><Trash2 :size="16"/></button></div></div><p v-if="!dimension.options.length" class="muted">请至少配置一个选项。</p></section></fieldset><footer class="governance-editor-actions"><span>当前草稿 r{{selectedDimension?.revision??0}}</span><button v-if="selectedDimension&&!selectedDimension.deprecated" type="button" class="btn btn-ghost" :disabled="busy" @click="deprecate('dimensions')"><Archive :size="15"/>弃用</button><button class="btn" :disabled="busy||!dirty||selectedDimension?.deprecated"><Save :size="15"/>保存草稿</button><button type="button" class="btn btn-primary" :disabled="busy||dirty||!selectedDimension||selectedDimension.deprecated" @click="publish('dimensions')"><FileCheck2 :size="15"/>发布新版</button></footer><details v-if="selectedDimension?.versions.length" class="governance-history"><summary>已发布版本（{{selectedDimension.versions.length}}）</summary><button v-for="item in [...selectedDimension.versions].reverse()" :key="item.version" type="button" @click="preview=item">v{{item.version}} · {{date(item.publishedAt)}} <code>{{item.checksum.slice(0,12)}}</code><ChevronRight :size="14"/></button></details></form>
              <form v-else-if="template" @submit.prevent="saveTemplate"><div class="governance-editor-title"><div><h3>{{selectedTemplate?'编辑模板草稿':'新建组织模板'}}</h3><p>发布规范不会自动覆盖数据集正在使用的版本。</p></div><span v-if="dirty" class="badge">未保存</span></div><fieldset :disabled="busy||selectedTemplate?.deprecated"><div class="governance-form-grid"><label>ID<input v-model="template.id" required maxlength="64" pattern="[a-z][a-z0-9_-]*" :readonly="!!selectedTemplate"/></label><label>模板名称<input v-model="template.name" required maxlength="120"/></label></div><label>用途层级<select v-model="template.targetKind" @change="changeTemplateKind" :disabled="!!selectedTemplate?.versions.length"><option value="dataset">数据集标签模板</option><option value="sample">样本标签模板</option><option v-if="template.targetKind==='legacy'" value="legacy">旧混合兼容规范</option></select></label><label>领域<select v-model="template.domain"><option v-for="item in domains" :key="item" :value="item">{{domainName(item)}}</option></select></label><label>用途说明<textarea v-model="template.description" rows="3" maxlength="2000"/></label><section class="governance-bindings"><header><strong>维度与适用范围</strong><button type="button" class="btn btn-ghost" :disabled="!publishedDimensions.length" @click="addBinding"><Plus :size="14"/>加入维度</button></header><p v-if="!publishedDimensions.length" class="muted">先创建并发布维度，或从预设另存模板。</p><article v-for="(binding,index) in template.bindings" :key="index"><div class="governance-form-grid"><label>维度<select v-model="binding.dimensionId" @change="updateBinding(index)"><option v-for="item in publishedDimensions" :key="item.id" :value="item.id">{{item.draft.displayName}} · {{item.id}}</option></select></label><div class="governance-binding-definition"><span>已采用的维度定义</span><strong v-if="bindingStatus(binding.dimensionId,binding.dimensionVersion).selected">{{bindingStatus(binding.dimensionId,binding.dimensionVersion).selected?.displayName}} <small>v{{binding.dimensionVersion}}</small></strong><p v-if="bindingStatus(binding.dimensionId,binding.dimensionVersion).status==='latest'">当前最新已发布定义</p><template v-else-if="bindingStatus(binding.dimensionId,binding.dimensionVersion).status==='pinned'"><p>此模板保留原定义；已有新发布内容可供采用。</p><button type="button" class="btn btn-ghost" @click="updateBinding(index)">采用最新已发布定义</button></template><p v-else class="notice">尚无可用的发布定义。请先发布此维度，再加入模板。</p></div></div><details class="governance-binding-advanced"><summary>高级：选择其他已发布定义</summary><p>模板发布时会记录所选定义，保证已有标注含义稳定。更改此处只修改当前草稿；保存并发布新版后，项目仍需明确采用。</p><label>发布定义<select v-model="binding.dimensionVersion"><option v-for="item in [...(bindingDimension(binding.dimensionId)?.versions??[])].reverse()" :key="item.version" :value="item.version">v{{item.version}} · {{item.displayName}}</option></select></label></details><div class="governance-binding-controls"><label v-for="scope in availableScopes" :key="scope" class="governance-check"><input v-model="binding.scopes" type="checkbox" :value="scope"/>{{scopeName(scope)}}</label><label class="governance-check"><input v-model="binding.defaultVisible" type="checkbox"/>默认显示</label><label class="governance-check"><input v-model="binding.required" type="checkbox"/>必填</label><button type="button" class="icon-button" aria-label="上移维度" :disabled="index===0" @click="moveBinding(index,-1)"><ArrowUp :size="15"/></button><button type="button" class="icon-button" aria-label="下移维度" :disabled="index===template.bindings.length-1" @click="moveBinding(index,1)"><ArrowDown :size="15"/></button><button type="button" class="icon-button" aria-label="移除模板维度" @click="template.bindings.splice(index,1)"><Trash2 :size="15"/></button></div></article></section></fieldset><footer class="governance-editor-actions"><span>草稿 r{{selectedTemplate?.revision??0}}</span><button v-if="selectedTemplate?.versions.length" type="button" class="btn" :disabled="busy" @click="copyPublished"><Copy :size="14"/>另存发布版本</button><button v-if="selectedTemplate&&!selectedTemplate.deprecated" type="button" class="btn btn-ghost" :disabled="busy" @click="deprecate('templates')"><Archive :size="15"/>弃用</button><button class="btn" :disabled="busy||!dirty||selectedTemplate?.deprecated"><Save :size="15"/>保存草稿</button><button type="button" class="btn btn-primary" :disabled="busy||dirty||!selectedTemplate||selectedTemplate.deprecated" @click="publish('templates')"><FileCheck2 :size="15"/>发布新版</button></footer><details v-if="selectedTemplate?.versions.length" class="governance-history"><summary>已发布版本（{{selectedTemplate.versions.length}}）</summary><button v-for="item in [...selectedTemplate.versions].reverse()" :key="item.version" type="button" @click="preview=item">v{{item.version}} · {{date(item.publishedAt)}} <code>{{item.checksum.slice(0,12)}}</code><ChevronRight :size="14"/></button></details></form>
            </section>
          </div>
        </template>
        <section v-else-if="tab==='feedback'" class="panel governance-feedback"><header><h2>缺项反馈</h2><p>只处理维度、选项和规范说明；此页不提供私有样本正文。</p></header><article v-for="item in directory?.feedback" :key="item.id"><div><strong>{{item.dimensionId||item.templateId||'规范反馈'}}</strong><span class="badge">{{{open:'待处理',resolved:'已解决',declined:'未采纳'}[item.status]}}</span></div><p>{{item.reason}}</p><small>{{item.requestedOption?'建议选项：'+item.requestedOption+' · ':''}}{{item.authorName}} · {{date(item.createdAt)}}</small><p v-if="item.response" class="governance-response">{{item.response}}</p><template v-if="item.status==='open'"><label>处理说明<textarea v-model="feedbackResponse[item.id]" rows="2" maxlength="2000" :disabled="busy"/></label><div class="governance-feedback-actions"><button class="btn" :disabled="busy||!feedbackResponse[item.id]?.trim()" @click="respond(item.id,'declined')">说明后不采纳</button><button class="btn btn-primary" :disabled="busy||!feedbackResponse[item.id]?.trim()" @click="respond(item.id,'resolved')">标记已解决</button></div></template></article><div v-if="!directory?.feedback.length" class="empty"><MessageSquareText :size="28"/><p>暂无缺项反馈</p></div></section>
        <section v-else class="panel governance-maintainers"><header><h2>指定组织维护者</h2><p>只有实例管理员可以授权。维护者不会因此获得项目数据访问、发布或分享权限。</p></header><form @submit.prevent="grantMaintainer(maintainerId,true)"><label>有效的独立身份<select v-model="maintainerId" required :disabled="busy"><option value="">选择协作者</option><option v-for="item in identities" :key="item.id" :value="item.id">{{item.name}} · {{item.id.slice(0,8)}}</option></select></label><button class="btn btn-primary" :disabled="busy||!maintainerId"><Plus :size="16"/>指定维护者</button></form><div v-for="item in org?.maintainers" :key="item.id" class="governance-maintainer"><div><strong>{{item.name}}</strong><code>{{item.id}}</code></div><button class="btn" :disabled="busy" @click="grantMaintainer(item.id,false)">撤销规范维护权</button></div><p v-if="!org?.maintainers.length" class="empty">尚未指定组织维护者，实例管理员仍可维护。</p></section>
        <details v-if="access.owner" class="governance-create-org"><summary>创建组织目录</summary><form @submit.prevent="createOrganization"><label>组织 ID<input v-model="newOrganizationId" required pattern="[a-z][a-z0-9_-]*" maxlength="64" placeholder="与项目 namespace 一致"/></label><label>显示名称<input v-model="newOrganizationName" required maxlength="120"/></label><button class="btn" :disabled="busy">创建组织</button></form></details>
      </section>
    </div>
    <div v-if="copyOpen" class="modal-backdrop" @click.self="!busy&&(copyOpen=false)"><section class="modal governance-modal" role="dialog" aria-modal="true" aria-labelledby="copy-template-title"><header><h2 id="copy-template-title">{{copySource?'从已发布版本另存':'从预制模板另存'}}</h2><button class="icon-button" :disabled="busy" aria-label="关闭" @click="copyOpen=false"><X :size="18"/></button></header><form @submit.prevent="copy"><fieldset :disabled="busy"><label v-if="!copySource">预制模板<select v-model="copyPreset"><option v-for="item in filteredPresets" :key="item.id" :value="item.id">{{item.name}} · {{item.columns.length}} 个维度</option></select></label><label>组织模板 ID<input v-model="copyId" required pattern="[a-z][a-z0-9_-]*" maxlength="64"/></label><label>模板名称<input v-model="copyName" required maxlength="120"/></label><p class="muted">复制后生成独立草稿，复用本组织已存在的同语义发布维度；不会更改任何项目的数据或当前绑定。</p></fieldset><div class="modal-actions"><button type="button" class="btn" :disabled="busy" @click="copyOpen=false">取消</button><button class="btn btn-primary" :disabled="busy"><Copy :size="15"/>另存草稿</button></div></form></section></div>
    <div v-if="preview" class="modal-backdrop" @click.self="preview=undefined"><section class="modal governance-modal governance-version-preview" role="dialog" aria-modal="true" aria-label="不可变发布版本"><header><div><h2>{{'name'in preview?preview.name:preview.displayName}} · v{{preview.version}}</h2><p>已发布不可变快照 · {{date(preview.publishedAt)}}</p></div><button class="icon-button" aria-label="关闭版本详情" @click="preview=undefined"><X :size="18"/></button></header><code class="governance-checksum">SHA-256 {{preview.checksum}}</code><p>{{preview.description}}</p><template v-if="'columns'in preview"><article v-for="column in preview.columns" :key="column.id"><strong>{{column.name}}</strong><code>{{column.id}}</code><p>{{column.description}}</p><small>{{column.options?.map(option=>option.displayName??option.value).join(' / ')||'文本'}} · {{column.scopes?.map(scopeName).join(' / ')}}</small></article></template><template v-else><article v-for="option in preview.options" :key="option.id"><strong>{{option.displayName}}</strong><code>{{option.id}}</code><p>{{option.description}}</p></article></template></section></div>
  </main>
</template>
